# Define the custom CUDA kernel for matrix multiplication with shared memory
matmul_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

#define TILE_SIZE 16

__global__ void matmul_kernel(const float* A, const float* B, float* C, int N) {
    __shared__ float sA[TILE_SIZE][TILE_SIZE];
    __shared__ float sB[TILE_SIZE][TILE_SIZE];

    int row = blockIdx.y * TILE_SIZE + threadIdx.y;
    int col = blockIdx.x * TILE_SIZE + threadIdx.x;

    float sum = 0.0f;

    for (int tile = 0; tile < (N + TILE_SIZE - 1) / TILE_SIZE; tile++) {
        // Load tile of A into shared memory
        int loadRow = row;
        int loadCol = tile * TILE_SIZE + threadIdx.x;
        if (loadRow < N && loadCol < N) {
            sA[threadIdx.y][threadIdx.x] = A[loadRow * N + loadCol];
        } else {
            sA[threadIdx.y][threadIdx.x] = 0.0f;
        }

        // Load tile of B into shared memory
        loadRow = tile * TILE_SIZE + threadIdx.y;
        loadCol = col;
        if (loadRow < N && loadCol < N) {
            sB[threadIdx.y][threadIdx.x] = B[loadRow * N + loadCol];
        } else {
            sB[threadIdx.y][threadIdx.x] = 0.0f;
        }

        __syncthreads();

        // Compute partial sum
        for (int k = 0; k < TILE_SIZE; k++) {
            sum += sA[threadIdx.y][k] * sB[k][threadIdx.x];
        }

        __syncthreads();
    }

    // Write result to global memory
    if (row < N && col < N) {
        C[row * N + col] = sum;
    }
}

