import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for matrix multiplication with shared memory and loop unrolling
matmul_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

#define TILE_SIZE 32
#define UNROLL_FACTOR 4

__global__ void matmul_kernel(const float* A, const float* B, float* C, int N) {
    __shared__ float sA[TILE_SIZE][TILE_SIZE];
    __shared__ float sB[TILE_SIZE][TILE_SIZE];

    int bx = blockIdx.x, by = blockIdx.y;
    int tx = threadIdx.x, ty = threadIdx.y;

    int row = by * TILE_SIZE + ty;
    int col = bx * TILE_SIZE + tx;

    float sum = 0.0f;

    for (int tile = 0; tile < (N + TILE_SIZE - 1) / TILE_SIZE; tile++) {
        // Load tile of A into shared memory (avoid bank conflicts)
        int loadRow = row;
        int loadCol = tile * TILE_SIZE + tx;
        if (loadRow < N && loadCol < N) {
            sA[ty][tx] = A[loadRow * N + loadCol];
        } else {
            sA[ty][tx] = 0.0f;
        }

        // Load tile of B into shared memory (avoid bank conflicts)
        int loadRowB = tile * TILE_SIZE + ty;
        int loadColB = col;
        if (loadRowB < N && loadColB < N) {
            sB[ty][tx] = B[loadRowB * N + loadColB];
        } else {
            sB[ty][tx] = 0.0f;
        }

        __syncthreads();

        // Compute partial sum with loop unrolling
        for (int k = 0; k < TILE_SIZE; k += UNROLL_FACTOR) {
            // Use register variables for unrolled computation
            float a0 = sA[ty][k];
            float a1 = sA[ty][k+1];
            float a2 = sA[ty][k+2];
            float a3 = sA[ty][k+3];

            float b0 = sB[k][tx];
            float b1 = sB[k+1][tx];
            float b2 = sB[k+2][tx];
            float b3 = sB[k+3][tx];

            sum += a0 * b0;
            sum += a1 * b1;
            sum += a2 * b2;
            sum += a3 * b3;
        }

        __syncthreads();
    }

    // Write result to global memory
    if (row < N && col < N) {
        C[row * N + col] = sum;
    }
}

torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B) {
    int N = A.size(0);
    auto C = torch::zeros_like(A);

    dim3 block(TILE_SIZE, TILE_SIZE);
    dim3 grid((N + block.x - 1) / block.x, (N + block.y - 1) / block.y);

    matmul_kernel<<<grid, block>>>(A.data_ptr<float>(), B.data_ptr<float>(), C.data_ptr<float>(), N);

    return C;
}
"""

