from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for matrix multiplication with vectorization and register blocking
matmul_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

#define TILE_SIZE 64
#define BLOCK_SIZE 16
#define VEC_SIZE 4

__global__ void matmul_kernel(const float* A, const float* B, float* C, int N) {
    // Define shared memory tiles
    __shared__ float sA[TILE_SIZE][TILE_SIZE + 1];  // +1 to avoid bank conflicts
    __shared__ float sB[TILE_SIZE][TILE_SIZE + 1];

    // Thread indices
    int tx = threadIdx.x;
    int ty = threadIdx.y;
    int bx = blockIdx.x;
    int by = blockIdx.y;

    // Each thread computes 4x4 output elements
    float sum[4][4] = {{0}};

    // Loop over tiles
    for (int tile = 0; tile < N / TILE_SIZE; tile++) {
        // Load A tile using float4 vectorization
        int loadRow = by * TILE_SIZE + ty * BLOCK_SIZE;
        int loadCol = tile * TILE_SIZE + tx * VEC_SIZE;

        float4 a4[BLOCK_SIZE];
        for (int i = 0; i < BLOCK_SIZE; i++) {
            if (loadRow + i < N && loadCol < N) {
                a4[i] = *reinterpret_cast<const float4*>(&A[(loadRow + i) * N + loadCol]);
            } else {
                a4[i] = {0, 0, 0, 0};
            }
        }

        // Load B tile using float4 vectorization
        int loadRowB = tile * TILE_SIZE + ty * BLOCK_SIZE;
        int loadColB = bx * TILE_SIZE + tx * VEC_SIZE;

        float4 b4[BLOCK_SIZE];
        for (int i = 0; i < BLOCK_SIZE; i++) {
            if (loadRowB + i < N && loadColB < N) {
                b4[i] = *reinterpret_cast<const float4*>(&B[(loadRowB + i) * N + loadColB]);
            } else {
                b4[i] = {0, 0, 0, 0};
            }
        }

        // Store A and B tiles in shared memory
        for (int i = 0; i < BLOCK_SIZE; i++) {
            int storeRow = ty * BLOCK_SIZE + i;
            sA[storeRow][tx * VEC_SIZE + 0] = a4[i].x;
            sA[storeRow][tx * VEC_SIZE + 1] = a4[i].y;
            sA[storeRow][tx * VEC_SIZE + 2] = a4[i].z;
            sA[storeRow][tx * VEC_SIZE + 3] = a4[i].w;

            sB[storeRow][tx * VEC_SIZE + 0] = b4[i].x;
            sB[storeRow][tx * VEC_SIZE + 1] = b4[i].y;
            sB[storeRow][tx * VEC_SIZE + 2] = b4[i].z;
            sB[storeRow][tx * VEC_SIZE + 3] = b4[i].w;
        }

        __syncthreads();

        // Compute with register blocking
        for (int k = 0; k < TILE_SIZE; k++) {
            float aReg[4];
            float bReg[4];

            for (int i = 0; i < 4; i++) {
                aReg[i] = sA[ty * 4 + i][k];
                bReg[i] = sB[k][tx * 4 + i];
            }

            for (int i = 0; i < 4; i++) {
                for (int j = 0; j < 4; j++) {
                    sum[i][j] += aReg[i] * bReg[j];
                }
            }
        }

        __syncthreads();
    }

    // Write results to global memory
    int outRow = by * TILE_SIZE + ty * 4;
    int outCol = bx * TILE_SIZE + tx * 4;

    for (int i = 0; i < 4; i++) {
        if (outRow + i < N) {
            for (int j = 0; j < 4; j++) {
                if (outCol + j < N) {
                    C[(outRow + i) * N + (outCol + j)] = sum[i][j];
                }
            }
        }
    }
}

torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B) {
    int N = A.size(0);
    auto C = torch::zeros_like(A);

    dim3 block(TILE_SIZE / 4, TILE_SIZE / 4);  // 16x16 threads
    dim3 grid((N + TILE_SIZE - 1) / TILE_SIZE, (N + TILE_SIZE - 1) / TILE_SIZE);

    matmul_kernel<<<grid, block>>>(A.data_ptr<float>(), B.data_ptr<float>(), C.data_ptr<float>(), N);

    return C;
}
"""

